\set ON_ERROR_STOP on
begin;
do $$declare t uuid:='10000000-0000-4000-8000-000000000001';author uuid:='00000000-0000-4000-8000-000000000001';reviewer uuid:='00000000-0000-4000-8000-000000000002';candidate uuid:='00000000-0000-4000-8000-000000000003';section_id uuid:='71000000-0000-4000-8000-000000000035';bank uuid;ids uuid[]:='{}';iid uuid;definition jsonb;witness jsonb;invalid_witness jsonb;result jsonb;definition_id uuid;version_id uuid;window_id uuid;registration uuid;manifest jsonb;changed jsonb;attempt uuid;payload jsonb;classes jsonb;n integer;before_scores jsonb;begin
 select jsonb_agg(to_jsonb(s) order by id) into before_scores from public.assessment_score_revisions s;
 bank:=(public.assessment_command(author,t,'blueprint-test-bank','bank.create','{"title":"Blueprint integration bank"}')->>'id')::uuid;
 begin perform public.assessment_command(author,t,'blueprint-bad-class','item.create',jsonb_build_object('bank_id',bank,'item','{"classification":{"topics":[],"estimated_difficulty":"calibrated"}}'::jsonb,'key','{}'::jsonb));raise exception 'Uncalibrated label accepted as calibrated metadata';exception when invalid_parameter_value then null;end;
 for n in 1..4 loop
  classes:=jsonb_build_object('topics',case n when 1 then '["Algebra","Reasoning"]'::jsonb when 2 then '["Algebra"]'::jsonb when 3 then '["Geometry"]'::jsonb else '["Geometry","Reasoning"]'::jsonb end,'estimated_difficulty',case when n in(2,3) then 'easy' else 'hard' end);
  payload:=jsonb_build_object('schema_version','assessment.item.v1','type','single_choice','prompt','Blueprint question '||n,'locale','en','max_score',case when n in(1,4) then 2 else 1 end,'tags','[]'::jsonb,'options','[{"id":"a","text":"A"},{"id":"b","text":"B"}]'::jsonb,'classification',classes);
  iid:=(public.assessment_command(author,t,'blueprint-item-create-'||n,'item.create',jsonb_build_object('bank_id',bank,'item',payload,'key','{"correct":"a"}'::jsonb))->>'id')::uuid;ids:=array_append(ids,iid);
  perform public.assessment_command(author,t,'blueprint-item-submit-'||n,'item.submit',jsonb_build_object('id',iid));perform public.assessment_command(reviewer,t,'blueprint-item-approve-'||n,'item.approve',jsonb_build_object('id',iid));
 end loop;
 definition:=jsonb_build_object('schema_version','assessment.definition.v2','title','Constrained placement','locale','en','duration_seconds',600,'shuffle_items',false,'shuffle_options',true,'sections',jsonb_build_array(jsonb_build_object('id',section_id,'title','Balanced section','draw_count',2,'item_version_ids',to_jsonb(ids),'blueprint',jsonb_build_object('schema_version','assessment.blueprint.v1','minimum_points',3,'maximum_points',3,'rules',jsonb_build_array(
  jsonb_build_object('id','72000000-0000-4000-8000-000000000001','label','Algebra exactly one','topics','["Algebra"]'::jsonb,'minimum',1,'maximum',1),
  jsonb_build_object('id','72000000-0000-4000-8000-000000000002','label','Easy exactly one','difficulties','["easy"]'::jsonb,'minimum',1,'maximum',1),
  jsonb_build_object('id','72000000-0000-4000-8000-000000000003','label','Reasoning coverage','topics','["Reasoning"]'::jsonb,'minimum',1,'maximum',2)
 )))));
 witness:=jsonb_build_array(jsonb_build_object('id',section_id,'item_version_ids',jsonb_build_array(ids[1],ids[3])));
 invalid_witness:=jsonb_build_array(jsonb_build_object('id',section_id,'item_version_ids',jsonb_build_array(ids[1],ids[2])));
 begin perform public.assessment_command(author,t,'blueprint-v1-downgrade','assessment.create',jsonb_build_object('definition',jsonb_set(definition,'{schema_version}','"assessment.definition.v1"'),'blueprint_witness',witness));raise exception 'Constrained definition was silently downgraded';exception when invalid_parameter_value then if sqlerrm<>'blueprint_definition_v2_required' then raise;end if;end;
 begin perform public.assessment_command(author,t,'blueprint-no-witness','assessment.create',jsonb_build_object('definition',definition));raise exception 'Blueprint accepted without satisfying witness';exception when check_violation then null;end;
 begin perform public.assessment_command(author,t,'blueprint-invalid-quota','assessment.create',jsonb_build_object('definition',definition,'blueprint_witness',invalid_witness));raise exception 'Overlapping quota bypass accepted';exception when check_violation then if sqlerrm<>'blueprint_quota_not_met' then raise;end if;end;
 begin perform public.assessment_command(author,t,'blueprint-invalid-points','assessment.create',jsonb_build_object('definition',definition,'blueprint_witness',jsonb_build_array(jsonb_build_object('id',section_id,'item_version_ids',jsonb_build_array(ids[2],ids[3])))));raise exception 'Points bound bypass accepted';exception when check_violation then if sqlerrm<>'blueprint_points_not_met' then raise;end if;end;
 result:=public.assessment_command(author,t,'blueprint-valid-create','assessment.create',jsonb_build_object('definition',definition,'blueprint_witness',witness));definition_id:=(result->>'id')::uuid;
 if public.assessment_command(author,t,'blueprint-valid-create','assessment.create',jsonb_build_object('definition',definition,'blueprint_witness',witness))<>result then raise exception 'Blueprint create receipt changed';end if;
 begin perform public.assessment_command(author,t,'blueprint-publish-forgery','assessment.publish',jsonb_build_object('id',definition_id,'revision',1,'blueprint_witness',invalid_witness));raise exception 'Publication accepted invalid witness';exception when check_violation then null;end;
 version_id:=(public.assessment_command(author,t,'blueprint-valid-publish','assessment.publish',jsonb_build_object('id',definition_id,'revision',1,'blueprint_witness',witness))->>'id')::uuid;
 if(select v.definition from public.assessment_versions v where v.id=version_id)<>definition then raise exception 'Publication lost pinned metadata/rules';end if;
 -- Replay must recover its committed publication even when working revision
 -- and derived witnesses subsequently change; neither is command identity.
 perform public.assessment_command(author,t,'blueprint-revise-after-publication','assessment.revise',jsonb_build_object('id',definition_id,'revision',1,'definition',definition||'{"title":"Updated blueprint working revision"}','reason','Later working revision after a lost publication reply.','blueprint_witness',witness));
 if(public.assessment_command(author,t,'blueprint-valid-publish','assessment.publish',jsonb_build_object('id',definition_id,'revision',1,'blueprint_witness',invalid_witness))->>'id')::uuid<>version_id then raise exception 'Publication replay was redefined by current working revision or derived witness';end if;
 window_id:=(public.assessment_command(author,t,'blueprint-active-window','window.create',jsonb_build_object('title','Blueprint candidate sitting','assessment_version_id',version_id,'opens_at',clock_timestamp()-interval '1 minute','closes_at',clock_timestamp()+interval '1 hour'))->>'id')::uuid;
 registration:=(public.assessment_command(author,t,'blueprint-candidate-register','registration.create',jsonb_build_object('window_id',window_id,'candidate_id',candidate,'extra_seconds',0))->>'id')::uuid;
 select jsonb_build_object(
  'schema_version','assessment.manifest.v1','assessment_version_id',version_id,'title',definition->'title','locale','en','duration_seconds',600,
  'sections',jsonb_build_array(jsonb_build_object('id',section_id,'title','Balanced section','items',jsonb_agg(
   jsonb_build_object('item_version_id',i.id,'section_id',section_id,'item',(i.payload-'classification')||jsonb_build_object('options','[{"id":"b","text":"B"},{"id":"a","text":"A"}]'::jsonb))
   order by chosen.ordinality
  )))
 ) into manifest from unnest(array[ids[1],ids[3]]) with ordinality chosen(id,ordinality) join public.assessment_item_versions i on i.id=chosen.id;
 begin perform public.assessment_command(candidate,t,'blueprint-forged-prompt','attempt.start',jsonb_build_object('registration_id',registration,'manifest',jsonb_set(manifest,'{sections,0,items,0,item,prompt}','"Forged question"'),'manifest_hash',repeat('a',64)));raise exception 'Candidate prompt forgery accepted';exception when check_violation then if sqlerrm<>'blueprint_prompt_mismatch' then raise;end if;end;
 begin perform public.assessment_command(candidate,t,'blueprint-forged-options','attempt.start',jsonb_build_object('registration_id',registration,'manifest',jsonb_set(manifest,'{sections,0,items,0,item,options,0,text}','"Forged option"'),'manifest_hash',repeat('a',64)));raise exception 'Candidate option forgery accepted';exception when check_violation then if sqlerrm<>'blueprint_option_mismatch' then raise;end if;end;
 begin perform public.assessment_command(candidate,t,'blueprint-leaked-classification','attempt.start',jsonb_build_object('registration_id',registration,'manifest',jsonb_set(manifest,'{sections,0,items,0,item,classification}','{"topics":["Algebra"]}'),'manifest_hash',repeat('a',64)));raise exception 'Private classification admitted to candidate manifest';exception when check_violation then null;end;
 begin perform public.assessment_command(candidate,t,'blueprint-wrong-section','attempt.start',jsonb_build_object('registration_id',registration,'manifest',jsonb_set(manifest,'{sections,0,title}','"Other section"'),'manifest_hash',repeat('a',64)));raise exception 'Changed section contract accepted';exception when check_violation then null;end;
 attempt:=(public.assessment_command(candidate,t,'blueprint-valid-start','attempt.start',jsonb_build_object('registration_id',registration,'manifest',manifest,'manifest_hash',repeat('a',64)))->>'id')::uuid;
 if public.assessment_command(candidate,t,'blueprint-valid-start','attempt.start',jsonb_build_object('registration_id',registration,'manifest',manifest,'manifest_hash',repeat('a',64)))->>'id'<>attempt::text then raise exception 'Start replay changed blueprint form';end if;
 if(select count(*) from public.assessment_forms f join public.assessment_attempts a on a.form_id=f.id where a.id=attempt)<>1 or exists(select 1 from public.assessment_forms f join public.assessment_attempts a on a.form_id=f.id where a.id=attempt and f.manifest::text like '%classification%') then raise exception 'Form duplicated or private classification leaked';end if;
 if(select jsonb_agg(to_jsonb(s) order by id) from public.assessment_score_revisions s) is distinct from before_scores then raise exception 'Blueprint changed academic scores';end if;
 if has_function_privilege('service_role','public.assessment_command_before_blueprints(uuid,uuid,text,text,jsonb)','execute') or has_function_privilege('authenticated','public.assessment_validate_blueprint_selection(uuid,jsonb,jsonb)','execute') then raise exception 'Private blueprint bypass exposed';end if;
end;$$;
rollback;
